  `a_ctname_twn` varchar(60) NOT NULL DEFAULT '',
  `a_ctdesc_twn` text NOT NULL,
  `a_ctname_jpn` varchar(60) NOT NULL DEFAULT '',
  `a_ctdesc_jpn` text NOT NULL,
  `a_ctname_usa` varchar(60) NOT NULL DEFAULT '',
