CREATE TABLE `t_magic` (
  `a_index` int(11) NOT NULL DEFAULT 0,
  `a_name` varchar(20) NOT NULL DEFAULT '',
  `a_maxlevel` tinyint(4) NOT NULL DEFAULT 0,
  `a_type` tinyint(4) NOT NULL DEFAULT 0,
  `a_subtype` tinyint(4) NOT NULL DEFAULT 0,
  `a_damagetype` tinyint(4) NOT NULL DEFAULT 0,
  `a_hittype` tinyint(4) NOT NULL DEFAULT 0,
  `a_attribute` tinyint(4) NOT NULL DEFAULT 0,
  `a_psp` int(11) NOT NULL DEFAULT 0,
  `a_ptp` int(11) NOT NULL DEFAULT 0,
  `a_hsp` int(11) NOT NULL DEFAULT 0,
  `a_htp` int(11) NOT NULL DEFAULT 0,
  `a_togle` tinyint(1) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`a_index`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;
