  `a_wear_type` int(11) NOT NULL DEFAULT 0,
  `a_accessory_type` int(11) NOT NULL DEFAULT 0,
  `a_name_thai` varchar(50) NOT NULL DEFAULT '',
  `a_name_thai_eng` varchar(50) NOT NULL DEFAULT '',
  `a_name_jpn` varchar(50) NOT NULL DEFAULT '',
  `a_name_mal` varchar(50) CHARACTER SET latin1 COLLATE latin1_bin NOT NULL DEFAULT '',
  `a_name_mal_eng` varchar(50) CHARACTER SET latin1 COLLATE latin1_bin NOT NULL DEFAULT '',
  `a_name_usa` varchar(50) NOT NULL DEFAULT '',
  `a_name_brz` varchar(50) NOT NULL DEFAULT '',
  `a_name_hk` varchar(50) DEFAULT NULL,
  `a_name_hk_eng` varchar(50) DEFAULT NULL,
  `a_name_ger` varchar(50) DEFAULT NULL,
  `a_name_spn` varchar(50) NOT NULL DEFAULT '',
  `a_name_frc` varchar(50) NOT NULL DEFAULT '',
  `a_name_pld` varchar(50) NOT NULL DEFAULT '',
  `a_name_rus` varchar(50) NOT NULL DEFAULT '',
  `a_name_tur` varchar(50) NOT NULL DEFAULT '',
  `a_name_spn2` varchar(50) NOT NULL DEFAULT '',
  `a_name_frc2` varchar(50) NOT NULL DEFAULT '',
  `a_name_ita` varchar(50) NOT NULL DEFAULT '',
  `a_name_mex` varchar(50) NOT NULL DEFAULT '',
  `a_name_nld` varchar(50) NOT NULL DEFAULT '',
  `a_name_dev` varchar(50) NOT NULL DEFAULT '',
  PRIMARY KEY (`a_index`)
) ENGINE=MyISAM AUTO_INCREMENT=107 DEFAULT CHARSET=latin1;
