  `a_canusemempos` tinyint(4) NOT NULL DEFAULT 0,
  `a_poscount` tinyint(4) NOT NULL DEFAULT 0,
  `a_posylayer` varchar(255) NOT NULL DEFAULT '',
  `a_posleft` varchar(255) NOT NULL DEFAULT '',
  `a_postop` varchar(255) NOT NULL DEFAULT '',
  `a_posright` varchar(255) NOT NULL DEFAULT '',
  `a_posbottom` varchar(255) NOT NULL DEFAULT '',
  `a_posmemo` text NOT NULL,
  `a_cansummonpet` tinyint(4) NOT NULL DEFAULT 0,
  `a_canmountpet` tinyint(4) NOT NULL DEFAULT 0,
  `a_continent_no` tinyint(4) NOT NULL DEFAULT -1,
  `a_minlevel` int(3) unsigned NOT NULL DEFAULT 0,
  `a_maxlevel` int(3) unsigned NOT NULL DEFAULT 999,
  `a_flag` int(11) NOT NULL DEFAULT 0,
  `a_treasurecount` tinyint(4) unsigned NOT NULL DEFAULT 0,
  `a_treasure_area` varchar(255) NOT NULL DEFAULT '',
